<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/seafort/app/bootstrap.php';
require_once dirname(__DIR__,2).'/seafort/app/references.php';
sf_admin_session();
if (empty($_SESSION['authenticated'])) {header('Location: /admin/',true,303);exit;}
$base='/admin/references.php';
$tab=in_array($_GET['tab']??'',['logos','quotes','settings'],true)?$_GET['tab']:'logos';
$error='';$notice='';$draft=null;$editId=is_string($_GET['edit']??null)?$_GET['edit']:'';$isNew=isset($_GET['new']);
function sf_ref_admin_redirect(string $base,string $tab,array $extra=[]): never {header('Location: '.$base.'?'.http_build_query(['tab'=>$tab]+$extra),true,303);exit;}
if (($_SERVER['REQUEST_METHOD']??'')==='POST') {
    $newUpload='';
    try {
        sf_require_csrf();$action=is_string($_POST['action']??null)?$_POST['action']:'';
        if ($action==='logout') {sf_logout();header('Location: /admin/',true,303);exit;}
        if ($action==='save_configuration') {
            $configuration=['settings'=>is_array($_POST['settings']??null)?$_POST['settings']:[],'custom_page'=>is_array($_POST['custom_page']??null)?$_POST['custom_page']:[]];
            if (isset($_FILES['custom_cover']) && ($_FILES['custom_cover']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE) $configuration['custom_page']['cover']=$newUpload=sf_store_upload($_FILES['custom_cover']);
            if (($_POST['remove_custom_cover']??'')==='1') $configuration['custom_page']['cover']='';
            sf_reference_save_configuration($configuration,is_string($_POST['revision']??null)?$_POST['revision']:'');
            $_SESSION['reference_notice']='Başlıklar ve Ege Deniz sayfa ayarları kaydedildi. Eksik veya izinsiz içerik ziyaretçilere gösterilmez.';
            sf_ref_admin_redirect($base,'settings');
        }
        $type=sf_reference_type(is_string($_POST['type']??null)?$_POST['type']:'');$tab=$type;
        $id=is_string($_POST['id']??null)&&$_POST['id']!==''?$_POST['id']:null;
        $revision=is_string($_POST['revision']??null)?$_POST['revision']:'';
        if ($action==='save') {
            $keys=$type==='logos'?['name','relationship','image','image_alt','href','source_note']:['quote','name','role','company','href','source_note'];
            $draft=[];foreach(array_merge($keys,['status','order','permission']) as $key)$draft[$key]=is_string($_POST[$key]??null)?$_POST[$key]:'';
            $editId=$id??'';$isNew=$id===null;$check=$draft;$check['status']='draft';sf_reference_validate($type,$check);
            if ($type==='logos') {
                if(isset($_FILES['logo_upload'])&&($_FILES['logo_upload']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE)$draft['image']=$newUpload=sf_store_upload($_FILES['logo_upload']);
                if(($_POST['remove_image']??'')==='1')$draft['image']='';
            }
            $saved=sf_reference_save($type,$draft,$id,$id!==null?$revision:null);
            $_SESSION['reference_notice']=$draft['status']==='published'?'Onaylı kayıt yayımlandı.':'Taslak kaydedildi; ziyaretçiler bu kaydı görmez.';
            sf_ref_admin_redirect($base,$type,['edit'=>$saved]);
        }
        if ($action==='delete' && $id!==null) {
            if(($_POST['confirm_delete']??'')!=='1')throw new InvalidArgumentException('Kalıcı silme onayını işaretleyin.');
            sf_reference_delete($type,$id,$revision);$_SESSION['reference_notice']='Referans kaydı silindi. Başka yerde kullanılıyor olabilecek görsel dosyası korundu.';
            sf_ref_admin_redirect($base,$type);
        }
        throw new InvalidArgumentException('İşlem tanınmadı.');
    } catch(InvalidArgumentException $exception) {$error=$exception->getMessage();}
    catch(Throwable) {$error='İşlem tamamlanamadı. Mevcut kayıtlar korunuyor; dosya izinlerini kontrol edin.';}
    if ($newUpload!=='' && preg_match('~\A/uploads/[a-f0-9]{32}\.(?:jpg|png|webp)\z~D',$newUpload)) {
        @unlink(SF_PUBLIC_DIR.$newUpload);
        if (is_array($draft) && ($draft['image']??'')===$newUpload) $draft['image']=$editId!==''?(string)(sf_reference_find('logos',$editId)['image']??''):'';
    }
}
if(isset($_SESSION['reference_notice'])){$notice=(string)$_SESSION['reference_notice'];unset($_SESSION['reference_notice']);}
$data=sf_reference_data();$revision=sf_reference_revision();$items=$tab==='settings'?[]:sf_reference_items($tab,false);$item=null;
if($editId!==''&&$tab!=='settings'){$item=sf_reference_find($tab,$editId);if(!$item){$error='Kayıt bulunamadı.';$editId='';}}
if($isNew&&$tab!=='settings')$item=['id'=>'','status'=>'draft','order'=>min(9999,(count($items)+1)*10),'permission'=>false,'name'=>'','relationship'=>'','image'=>'','image_alt'=>'','href'=>'','source_note'=>'','quote'=>'','role'=>'','company'=>''];
if($draft!==null)$item=array_replace($item??[],$draft,['id'=>$editId]);
$relationships=['customer'=>'Müşteri','partner'=>'İş ortağı','supplier'=>'Tedarikçi'];
function sf_ref_admin_input(string $name,string $label,string $value,string $type='text',int $max=180): void {
    $id='ref-'.substr(hash('sha256',$name),0,15);
    echo '<div class="reference-field"><label for="'.$id.'">'.sf_escape($label).'</label><input id="'.$id.'" name="'.sf_escape($name).'" type="'.sf_escape($type).'" maxlength="'.$max.'" value="'.sf_escape($value).'"></div>';
}
function sf_ref_admin_area(string $name,string $label,string $value,int $max=1500,int $rows=4): void {
    $id='ref-'.substr(hash('sha256',$name),0,15);
    echo '<div class="reference-field"><label for="'.$id.'">'.sf_escape($label).'</label><textarea id="'.$id.'" name="'.sf_escape($name).'" maxlength="'.$max.'" rows="'.$rows.'">'.sf_escape($value).'</textarea></div>';
}
